package cn.workbench;
import org.springframework.web.bind.annotation.*;import jakarta.servlet.http.HttpServletRequest;import java.util.*;import java.time.*;import java.math.*;import static cn.workbench.Records.*;
@RestController @RequestMapping("/api/v1") public class KpiController {
 final Records r;final Store db;final Policy p;final Writes w;final Jsons json;
 public KpiController(Records r,Store db,Policy p,Writes w,Jsons json){this.r=r;this.db=db;this.p=p;this.w=w;this.json=json;}
 @GetMapping("/kpi/templates") Object templates(HttpServletRequest q){var a=p.actor(q);if(!a.leader()&&!a.departmentHead()&&!a.administrator())throw ApiException.denied();return Api.ok(r.list("KPI_TEMPLATE",null,null));}
 @GetMapping("/kpi/runs") Object runs(HttpServletRequest q,@RequestParam(required=false)Integer companyId){var a=p.actor(q);int company=companyId==null?Objects.requireNonNullElse(a.company(),0):companyId;p.company(a,company);if(!a.leader()&&!a.departmentHead()&&!a.administrator())throw ApiException.denied();return Api.ok(r.list("KPI_RUN",company,null).stream().map(run->{var view=publicRun(run);view.put("allowedActions",a.administrator()?List.of("unlock"):List.of());return view;}).toList());}
 @GetMapping("/kpi/scores") Object scores(HttpServletRequest q,@RequestParam(required=false)String period,@RequestParam(required=false)Integer companyId){return Api.ok(scoresData(p.actor(q),period,companyId));}
 List<Map<String,Object>> scoresData(Policy.Actor a,String period,Integer companyId){if(!a.leader()&&!a.departmentHead())throw ApiException.denied();Integer company=companyId==null?a.company():companyId;if(company!=null)p.company(a,company);return r.list("KPI_SCORE",company,a.leader()?null:a.dept()).stream().filter(s->{var run=r.get(Jsons.number(s.get("runId")));return period==null||period.equals(run.get("period"));}).map(s->{var run=r.get(Jsons.number(s.get("runId")));var v=new LinkedHashMap<>(s);v.put("period",run.get("period"));v.put("simulation",run.get("simulation"));v.put("templateId",run.get("templateId"));v.put("finalScore",s.get("adjustedScore")==null?s.get("rawScore"):s.get("adjustedScore"));v.put("locked",locked(run));v.put("status",Boolean.TRUE.equals(run.get("simulation"))?"SIMULATION":locked(run)?"LOCKED":"PUBLISHED");v.put("appeals",r.list("KPI_APPEAL",TaskService.integer(s,"companyId"),TaskService.integer(s,"deptId")).stream().filter(x->Jsons.number(x.get("scoreId"))==Jsons.number(s.get("id"))).map(appeal->{var out=new LinkedHashMap<>(appeal);out.put("allowedActions",a.leader()&&!locked(run)&&"PENDING".equals(appeal.get("status"))?List.of("resolve"):List.of());return out;}).toList());v.put("allowedActions",locked(run)?List.of():a.leader()?List.of("appeal","adjust"):List.of("appeal"));return (Map<String,Object>)v;}).toList();}
 @PostMapping("/admin/kpi/runs") Object calculate(@RequestBody Map<String,Object>b,HttpServletRequest q){var a=p.actor(q);p.admin(a);p.freshTotp(q);return w.run(q,b,()->publicRun((Map<String,Object>)run(a,b)));}
 static Map<String,Object> publicRun(Map<String,Object> run){var view=new LinkedHashMap<>(run);view.remove("inputSnapshot");return view;}
 Object run(Policy.Actor a,Map<String,Object>b){int company=TaskService.integer(b,"companyId");p.company(a,company);String period=TaskService.text(b,"period",7);YearMonth month;try{month=YearMonth.parse(period);}catch(Exception e){throw TaskService.invalid("期间格式须为YYYY-MM");}if(!month.isBefore(YearMonth.now(ZoneId.of("Asia/Shanghai"))))throw TaskService.invalid("仅能结算已结束月份");long templateId=TaskService.number(b,"templateId");var template=r.get(templateId);if(!template.get("kind").equals("KPI_TEMPLATE"))throw ApiException.denied();boolean simulation=Boolean.TRUE.equals(b.get("simulation"));if(!simulation&&(!Boolean.TRUE.equals(template.get("approved"))||!"[30,25,20,10,15]".equals(template.get("weightsJson"))))throw TaskService.invalid("未批准模板只能模拟");var key=map("company",company,"period",period,"template",templateId);if(!simulation){Long existing=db.runFor(key);if(existing!=null)return r.get(existing);}Instant start=month.atDay(1).atStartOfDay(ZoneId.of("Asia/Shanghai")).toInstant(),end=month.plusMonths(1).atDay(1).atStartOfDay(ZoneId.of("Asia/Shanghai")).toInstant();var inputs=r.list("SUB_TASK",company,null).stream().filter(s->{Instant deadline=instant(s.get("deadline"));return !deadline.isBefore(start)&&deadline.isBefore(end);}).map(s->{var v=new LinkedHashMap<>(s);var task=r.get(Jsons.number(s.get("taskId")));TaskService.preserveSubOverdue(v);v.put("taskStatus",task.get("status"));return (Map<String,Object>)v;}).filter(s->!"DRAFT".equals(s.get("taskStatus"))).toList();var run=r.create("KPI_RUN",company,null,null,a.uid(),simulation?"SIMULATION":"PUBLISHED",map("period",period,"templateId",templateId,"simulation",simulation,"publishedAt",Instant.now().toString(),"lockedAt",null,"inputSnapshot",json.write(map("template",template,"subTasks",inputs)),"timezone","Asia/Shanghai"));long runId=Jsons.number(run.get("id"));if(!simulation){key.put("run",runId);db.runKey(key);}for(var dept:r.list("DEPARTMENT",company,null)){int deptId=Jsons.integer(dept.get("id"));var subs=inputs.stream().filter(s->TaskService.integer(s,"deptId")==deptId&&!"CANCELLED".equals(s.get("taskStatus"))).toList();var metrics=metrics(subs);var values=Kpi.evaluate(decimal(metrics.get("timelyRate")),decimal(metrics.get("overdueRate")),decimal(metrics.get("reworkRate")),decimal(metrics.get("responseHours")),decimal(metrics.get("executionHours")));BigDecimal raw=Kpi.calculate(values);r.create("KPI_SCORE",company,deptId,null,a.uid(),"PUBLISHED",map("runId",runId,"rawScore",raw,"adjustedScore",null,"metricsJson",json.write(metrics),"metrics",metrics,"indicatorScores",values,"departmentName",dept.get("name"),"sampleCount",subs.size(),"notApplicable",raw==null,"templateVersion",template.get("templateVersion")));}w.audit(a,simulation?"KPI_SIMULATE":"KPI_PUBLISH",runId);return run;}
 static BigDecimal decimal(Object v){return v==null?null:new BigDecimal(v.toString());}
 static Map<String,Object> metrics(List<Map<String,Object>> subs){BigDecimal total=BigDecimal.valueOf(subs.size());long timely=subs.stream().filter(s->s.get("submittedAt")!=null&&!instant(s.get("submittedAt")).isAfter(instant(s.get("deadline")))).count();long overdue=subs.stream().filter(s->Boolean.TRUE.equals(s.get("everOverdue"))||(s.get("submittedAt")==null?instant(s.get("deadline")).isBefore(Instant.now()):instant(s.get("submittedAt")).isAfter(instant(s.get("deadline"))))).count();long accepted=subs.stream().filter(s->"ACCEPTED".equals(s.get("status"))).count();long rework=subs.stream().filter(s->"ACCEPTED".equals(s.get("status"))&&s.get("rejectCount")!=null&&Jsons.integer(s.get("rejectCount"))>0).count();List<BigDecimal> response=new ArrayList<>(),execution=new ArrayList<>();for(var s:subs){if(s.get("firstReceivedAt")!=null){Object dispatched=s.getOrDefault("dispatchedAt",s.get("createdAt"));if(dispatched!=null)response.add(BigDecimal.valueOf(Duration.between(instant(dispatched),instant(s.get("firstReceivedAt"))).toSeconds()).divide(new BigDecimal("3600"),10,RoundingMode.HALF_UP));if(s.get("submittedAt")!=null)execution.add(BigDecimal.valueOf(Duration.between(instant(s.get("firstReceivedAt")),instant(s.get("submittedAt"))).toSeconds()).divide(new BigDecimal("3600"),10,RoundingMode.HALF_UP));}}return map("timelyRate",Kpi.ratio(BigDecimal.valueOf(timely),total),"overdueRate",Kpi.ratio(BigDecimal.valueOf(overdue),total),"reworkRate",Kpi.ratio(BigDecimal.valueOf(rework),BigDecimal.valueOf(accepted)),"responseHours",average(response),"executionHours",average(execution),"denominator",subs.size());}
 static BigDecimal average(List<BigDecimal> values){return values.isEmpty()?null:values.stream().reduce(BigDecimal.ZERO,BigDecimal::add).divide(BigDecimal.valueOf(values.size()),10,RoundingMode.HALF_UP);}
 boolean locked(Map<String,Object> run){if(Boolean.TRUE.equals(run.get("simulation")))return true;if(run.get("unlockUntil")!=null&&instant(run.get("unlockUntil")).isAfter(Instant.now()))return false;return !Instant.now().isBefore(instant(run.get("publishedAt")).plus(Duration.ofDays(7)));}
 Map<String,Object> score(Policy.Actor a,long id){var s=r.lock(id);if(!s.get("kind").equals("KPI_SCORE"))throw ApiException.denied();p.company(a,TaskService.integer(s,"companyId"));if(!a.leader()&&(!a.departmentHead()||!Objects.equals(a.dept(),TaskService.integer(s,"deptId"))))throw ApiException.denied();return s;}
 @PostMapping("/kpi/scores/{id}/appeals") Object appeal(@PathVariable long id,@RequestBody Map<String,Object>b,HttpServletRequest q){var a=p.actor(q);return w.run(q,b,()->{var s=score(a,id);var run=r.lock(TaskService.number(s,"runId"));if(locked(run)||Boolean.TRUE.equals(run.get("simulation")))throw new ApiException(409,"OBJECTION_CLOSED","七天异议期已结束");var existing=r.list("KPI_APPEAL",TaskService.integer(s,"companyId"),TaskService.integer(s,"deptId")).stream().filter(x->TaskService.number(x,"scoreId")==id&&"PENDING".equals(x.get("status"))).toList();if(!existing.isEmpty())throw ApiException.conflict();var appeal=r.create("KPI_APPEAL",TaskService.integer(s,"companyId"),TaskService.integer(s,"deptId"),null,a.uid(),"PENDING",map("scoreId",id,"applicantId",a.uid(),"reason",TaskService.text(b,"reason",1000),"decision",null));w.audit(a,"KPI_APPEAL",Jsons.number(appeal.get("id")));return appeal;});}
 @PostMapping("/kpi/appeals/{id}/resolve") Object resolve(@PathVariable long id,@RequestBody Map<String,Object>b,HttpServletRequest q){var a=p.actor(q);p.freshTotp(q);return w.run(q,b,()->{var appeal=r.lock(id);if(!appeal.get("kind").equals("KPI_APPEAL"))throw ApiException.denied();p.leader(a,TaskService.integer(appeal,"companyId"));var s=score(a,TaskService.number(appeal,"scoreId"));if(locked(r.get(TaskService.number(s,"runId"))))throw new ApiException(409,"KPI_LOCKED","结算已锁定");Domain.require((String)appeal.get("status"),"PENDING");String decision=TaskService.text(b,"decision",30);if(!Set.of("APPROVED","REJECTED","ACCEPT","REJECT").contains(decision))throw TaskService.invalid("决定无效");appeal.put("decision",decision);appeal.put("status",decision);appeal.put("resolutionReason",TaskService.text(b,"reason",1000));appeal.put("resolvedBy",a.uid());appeal.put("resolvedAt",Instant.now().toString());r.save(appeal);w.audit(a,"KPI_APPEAL_RESOLVE",id);return appeal;});}
 @PostMapping("/kpi/scores/{id}/adjust") Object adjust(@PathVariable long id,@RequestBody Map<String,Object>b,HttpServletRequest q){var a=p.actor(q);p.freshTotp(q);return w.run(q,b,()->{var s=score(a,id);p.leader(a,TaskService.integer(s,"companyId"));var run=r.lock(TaskService.number(s,"runId"));if(locked(run))throw new ApiException(409,"KPI_LOCKED","结算已锁定，需授权解锁");BigDecimal value=decimal(b.get("score"));if(value==null||value.signum()<0||value.compareTo(new BigDecimal("100"))>0)throw TaskService.invalid("分数须介于0至100");String reason=TaskService.text(b,"reason",1000);r.create("KPI_ADJUSTMENT",TaskService.integer(s,"companyId"),TaskService.integer(s,"deptId"),null,a.uid(),"APPLIED",map("scoreId",id,"actorId",a.uid(),"score",value,"reason",reason,"previousScore",s.get("adjustedScore"),"unlockReason",run.get("unlockReason")));s.put("adjustedScore",value);r.save(s);w.audit(a,"KPI_ADJUST",id);return s;});}
 @PostMapping("/admin/kpi/runs/{id}/unlock") Object unlock(@PathVariable long id,@RequestBody Map<String,Object>b,HttpServletRequest q){var a=p.actor(q);p.admin(a);p.freshTotp(q);return w.run(q,b,()->{var run=r.lock(id);if(!run.get("kind").equals("KPI_RUN"))throw ApiException.denied();p.company(a,TaskService.integer(run,"companyId"));run.put("unlockReason",TaskService.text(b,"reason",1000));run.put("unlockUntil",Instant.now().plus(Duration.ofMinutes(15)).toString());r.save(run);w.audit(a,"KPI_UNLOCK",id);return run;});}
}
